test('owned provider status refreshes after normal Send Undo so the same restored draft stays usable without keyless Send',async()=>{
 const backend=providerAppFixture(),app=await mount('Managed authored body',{...backend.fixture,providerRequest:request=>{
  if(request.path==='/api/drafts/synthetic-draft/send-operations'&&request.method==='POST')backend.setSnapshot({...backend.getSnapshot(),revision:backend.getSnapshot().revision+1,state:'suspended',deliveryBlocked:true});
  if(request.path.startsWith('/api/draft-send-operations/')&&request.path.endsWith('/cancel')){backend.getRecord().revision++;backend.setSnapshot({...backend.getSnapshot(),revision:backend.getSnapshot().revision+1,state:'queued',desiredRevision:backend.getRecord().revision,deliveryBlocked:false})}
  return backend.handler(request);
 }});try{await app.click('Send');assert.equal(app.host.querySelector('[aria-label="Message body"]'),null);await app.click('Undo');assert.equal(app.host.querySelector('[aria-label="Message body"]')?.textContent,'Managed authored body');assert.match(app.host.querySelector('.provider-draft-status')?.textContent||'',/Saved locally.*Gmail sync queued/);assert.equal(app.button('Send').disabled,false);assert.equal(app.button('Send later').disabled,false);assert.equal(app.requests.some(request=>request.path==='/api/drafts/synthetic-draft/send'),false);assert.equal(app.requests.filter(request=>request.path.endsWith('/send-operations')&&request.method==='POST').length,1)}finally{await app.close()}
});

